select  from distributor_settlement_record dsr
LEFT JOIN merchant m ON dsr.merchant_id = m.id
LEFT JOIN distributor d ON dsr.distributor_id = d.id

    dsr.del_flag = '0'
    and dsr.distributor_id = #{distributorId}
